function selectField(string $label,string $name,array $options,mixed $value='',bool $required=true): void { echo '<label>'.e($label).'<select name="'.e($name).'" '.(in_array($name,['student_id','invoice_id','teacher_id'],true)?'data-searchable ':'').($required?'required':'').'>'; foreach($options as $k=>$v) echo '<option value="'.e($k).'" '.((string)old($name,$value)===(string)$k?'selected':'').'>'.e($v).'</option>'; echo '</select></label>'; }
?>
