<div class="cards-grid"><?php foreach($classes as $c): $n=(int)\Mini\Database::fetchValue('SELECT COUNT(*) FROM batches WHERE class_id=?',[$c['id']]); $teacher=array_values(array_filter($teachers,fn($t)=>$t['id']==$c['teacher_id']))[0]['name']??'Not assigned'; ?><article class="panel class-card"><div class="teacher-top"><span class="stat-icon mint"><?= icon('book') ?></span><a class="text-link" href="<?= e(url('classes?edit='.$c['id'])) ?>">Edit class</a></div><h2><?= e($c['name']) ?></h2><p>Class teacher · <?= e($teacher) ?></p><div class="class-bar"><div><strong><?= $n ?> batches</strong><span>Fee: <?= money($c['fee']) ?></span></div></div><a class="panel-bottom" href="<?= e(url('classes/'.$c['id'].'/batches')) ?>">View batches <?= icon('arrow') ?></a></article><?php endforeach ?><?php if(!$classes): ?><div class="panel empty wide"><?= icon('book') ?><h3>Room for a bright beginning.</h3><p>Create your first class and assign a teacher.</p></div><?php endif ?></div>
<?php elseif($page==='settings'): ?>
