input('Full name','name','text',$edit['name']??''); input('Subject / specialty','subject','text',$edit['subject']??''); input('Email','email','email',$edit['email']??'',false); input('Phone','phone','tel',$edit['phone']??'',false);
elseif($page==='classes'):
input('Class name','name','text',$edit['name']??''); input('Default batch capacity','capacity','number',$edit['capacity']??30); input('Class fee','fee','number',$edit['fee']??0); selectField('Class teacher','teacher_id',[''=>'Not assigned']+array_column($teachers,'name','id'),$edit['teacher_id']??'',false);
endif ?></div><div class="form-footer"><button type="button" class="button" data-close>Cancel</button><button class="button primary"><?= icon('check') ?> Save <?= e($labels[$page]) ?></button></div></form></dialog>
